{% comment %}
  Custom Liquid block to make "Start Claim" button open in a new tab.
  Add this as a "Custom liquid" section on the warranty page.
{% endcomment %}

<script>
(function() {
  function makeStartClaimOpenInNewTab() {
    // Find the "Start Claim" button link
    const startClaimLinks = Array.from(document.querySelectorAll('a')).filter(link => {
      const text = link.textContent.trim();
      const href = link.getAttribute('href') || '';
      return text === 'Start Claim' || href.includes('returns-portal/login');
    });

    startClaimLinks.forEach(link => {
      link.setAttribute('target', '_blank');
      link.setAttribute('rel', 'noopener noreferrer');
    });
  }

  // Run when DOM is ready
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', makeStartClaimOpenInNewTab);
  } else {
    makeStartClaimOpenInNewTab();
  }
})();
</script>
